// Build French localization data from the public PokeAPI CSV dataset.
// Usage: node scripts/build-fr-data.mjs [csv-dir]
// The generated file is committed so the game stays fully offline.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const dir = process.argv[2] || '/tmp/opencode'
const out = join(process.cwd(), 'js/data/localization.fr.js')

function parseCsv (text) {
  const rows = []
  let row = [], field = '', quoted = false
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (quoted) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++ } else quoted = false
      } else field += c
    } else if (c === '"') quoted = true
    else if (c === ',') { row.push(field); field = '' }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = '' }
    else if (c === '\r') { /* ignore */ }
    else field += c
  }
  if (field.length || row.length) { row.push(field); rows.push(row) }
  return rows
}

function load (name) {
  const p = join(dir, name)
  if (!existsSync(p)) throw new Error(`Missing ${p}. Download the PokeAPI CSV dataset first.`)
  return parseCsv(readFileSync(p, 'utf8'))
}

const FR = 5
const EN = 9

const names = {}
const genera = {}
for (const r of load('pokemon_species_names.csv').slice(1)) {
  if (+r[1] !== FR) continue
  const id = +r[0]
  names[id] = r[2]
  if (r[3]) genera[id] = r[3]
}

const flavor = {}
const flavorVersion = {}
for (const r of load('pokemon_species_flavor_text.csv').slice(1)) {
  if (+r[2] !== FR) continue
  const id = +r[0], version = +r[1]
  if (flavorVersion[id] && flavorVersion[id] > version) continue
  flavorVersion[id] = version
  flavor[id] = r[3].replace(/[\n\f\r]+/g, ' ').replace(/\s+/g, ' ').replace(/­/g, '').trim()
}

// English move name -> French move name
const moveEn = {}, moveFr = {}
for (const r of load('move_names.csv').slice(1)) {
  const id = +r[0], lang = +r[1]
  if (lang === EN) moveEn[id] = r[2]
  else if (lang === FR) moveFr[id] = r[2]
}
const moves = {}
for (const id of Object.keys(moveEn)) if (moveFr[id]) moves[moveEn[id]] = moveFr[id]

const banner = '// Generated by scripts/build-fr-data.mjs from the PokeAPI CSV dataset.\n// Do not edit by hand; rerun the script to refresh.\n'
const body = banner +
  `export const FR_NAMES = ${JSON.stringify(names)}\n\n` +
  `export const FR_GENERA = ${JSON.stringify(genera)}\n\n` +
  `export const FR_FLAVOR = ${JSON.stringify(flavor)}\n\n` +
  `export const FR_MOVES = ${JSON.stringify(moves)}\n`

mkdirSync(join(process.cwd(), 'js/data'), { recursive: true })
writeFileSync(out, body)
console.log(`Wrote ${out}: ${Object.keys(names).length} names, ${Object.keys(flavor).length} flavor texts, ${Object.keys(moves).length} moves.`)
